230.     /// Creates a new fixed-size bump allocator.
231.     ///
232.     /// # Returns
233.     ///
234.     /// Returns a new allocator.
235.     ///
236.     /// # Safety
237.     ///
238.     /// The caller must ensure that only **one** `FixedSizeBumpAllocator` instance exists for a
239.     /// given `S: BssStorage` backend at any time. Creating multiple allocators over the same
240.     /// backend causes independent bump counters, which leads to overlapping slot reservations
241.     /// and undefined behavior (multiple `&'static mut` references to the same memory).
242.     ///
243.     pub const unsafe fn new() -> Self {
244.         Self {
245.             next_slot: AtomicUsize::new(0),
246.             _storage: PhantomData,
247.         }
248.     }
249. 
250.     ///
251.     /// # Description
252.     ///
253.     /// Allocates the next fixed-size slot as a raw byte array.
254.     ///
255.     /// # Returns
256.     ///
257.     /// On success, returns a mutable reference to a unit-sized byte array.
258.     ///
259.     /// # Errors
260.     ///
261.     /// - [`BumpAllocError::Exhausted`] if storage capacity is exhausted.
262.     /// - [`BumpAllocError::Overflow`] if internal arithmetic overflows.
263.     /// - [`BumpAllocError::OutOfBounds`] if computed slot exceeds storage bounds.
264.     /// - [`BumpAllocError::Misaligned`] if computed slot is not properly aligned.
265.     ///
266.     // SAFETY-SPEC: `external_body` because the success path materializes a
267.     // `&'static mut [u8; N]` from a backend-provided address (`usize as *mut`), a
268.     // raw-memory operation Verus cannot verify without a `PointsTo` permission for
269.     // the externally-owned `BssStorage` region. Mirrors the `src/libs/raw-array`
270.     // pattern. Registered in `verus-ai-logs/tcb-allowed.md`.
271.     #[verus_verify(external_body)]
272.     #[verus_spec(result =>
273.         requires bump_view(self).inv(),
274.         ensures
275.             match result {
276.                 Ok(slot) => {
277.                     let v = bump_view(self);
278.                     let a = slot_ref_addr(slot);
279.                     &&& a % (v.unit_align as int) == 0
280.                     &&& v.base <= a
281.                     &&& a + (N as int) <= v.base + (v.storage_size as int)
282.                 },
283.                 Err(_) => true,
284.             },
285.     )]
286.     pub fn alloc(&self) -> Result<&'static mut [u8; N], BumpAllocError> {
287.         // Reserve a slot index via compare-and-swap to avoid overshooting the counter.
288.         let idx: usize = loop {
289.             let current: usize = self.next_slot.load(Ordering::Acquire);
290.             if current >= S::NUM_UNITS {
291.                 return Err(BumpAllocError::Exhausted);
292.             }
293.             let next: usize = current.checked_add(1).ok_or(BumpAllocError::Overflow)?;
294.             if self
295.                 .next_slot
296.                 .compare_exchange(current, next, Ordering::AcqRel, Ordering::Acquire)
297.                 .is_ok()
298.             {
299.                 break current;
300.             }
301.         };
302. 
303.         let stride: usize = align_up(N, A).ok_or(BumpAllocError::Overflow)?;
304.         let offset: usize = idx.checked_mul(stride).ok_or(BumpAllocError::Overflow)?;
305. 
306.         let base: usize = S::as_mut_ptr() as usize;
307.         let ptr: usize = base.checked_add(offset).ok_or(BumpAllocError::Overflow)?;
308.         let end: usize = ptr.checked_add(N).ok_or(BumpAllocError::Overflow)?;
309.         let storage_end: usize = base
310.             .checked_add(S::STORAGE_SIZE)
311.             .ok_or(BumpAllocError::Overflow)?;
312.         if end > storage_end {
313.             return Err(BumpAllocError::OutOfBounds);
314.         }
315.         if !ptr.is_multiple_of(A) {
316.             return Err(BumpAllocError::Misaligned);
317.         }
318. 
319.         // SAFETY: the backend contract guarantees valid stable storage; each slot index is handed
320.         // out at most once by atomic compare-and-swap.
321.         Ok(unsafe { &mut *(ptr as *mut [u8; N]) })
322.     }
323. 
324.     ///
325.     /// # Description
326.     ///
327.     /// Allocates the next fixed-size slot and reinterprets it as `MaybeUninit<T>`.
328.     ///
329.     /// # Returns
330.     ///
331.     /// On success, returns a mutable reference to an uninitialized `T`.
332.     ///
333.     /// # Errors
334.     ///
335.     /// - [`BumpAllocError::SizeMismatch`] if `size_of::<T>() != N`.
336.     /// - [`BumpAllocError::AlignmentMismatch`] if `align_of::<T>() > A`.
337.     /// - Any error from [`alloc()`](Self::alloc).
338.     ///
339.     /// # Safety
340.     ///
341.     /// The caller must initialise the returned `MaybeUninit<T>` before reading through it
342.     /// and ensure exclusive use of the returned reference.
343.     ///
344.     // SAFETY-SPEC: `external_body` for the same reason as `alloc` (it delegates to
345.     // `alloc` and then re-materializes the slot reference as `&'static mut
346.     // MaybeUninit<T>`). The size/alignment guard arms make the `T`-vs-`(N, A)`
347.     // contract caller-visible. Registered in `verus-ai-logs/tcb-allowed.md`.
348.     #[verus_verify(external_body)]
349.     #[verus_spec(result =>
350.         requires bump_view(self).inv(),
351.         ensures
352.             match result {
353.                 Ok(slot) => {
354.                     let v = bump_view(self);
355.                     let a = slot_ref_addr(slot);
356.                     &&& vstd::layout::size_of::<T>() == N as nat
357.                     &&& vstd::layout::align_of::<T>() <= A as nat
358.                     &&& a % (v.unit_align as int) == 0
359.                     &&& v.base <= a
360.                     &&& a + (N as int) <= v.base + (v.storage_size as int)
361.                 },
362.                 Err(BumpAllocError::SizeMismatch) => vstd::layout::size_of::<T>() != N as nat,
363.                 Err(BumpAllocError::AlignmentMismatch) => vstd::layout::align_of::<T>() > A as nat,
364.                 Err(_) => true,
365.             },
366.     )]
367.     pub unsafe fn alloc_as<T>(&self) -> Result<&'static mut MaybeUninit<T>, BumpAllocError> {
368.         if core::mem::size_of::<T>() != N {
369.             return Err(BumpAllocError::SizeMismatch);
370.         }
371.         if core::mem::align_of::<T>() > A {
372.             return Err(BumpAllocError::AlignmentMismatch);
373.         }
374. 
375.         let slot: &'static mut [u8; N] = self.alloc()?;
376.         // SAFETY: size/alignment checks above guarantee this cast is valid.
377.         Ok(unsafe { &mut *(slot.as_mut_ptr() as *mut MaybeUninit<T>) })
378.     }
379. }
380. 
381. impl<const N: usize, const A: usize, S: BssStorage> Default for FixedSizeBumpAllocator<N, A, S> {
382.     fn default() -> Self {
383.         // SAFETY: caller is responsible for the singleton invariant.
384.         unsafe { Self::new() }
385.     }
386. }
